  } finally {CloseHandle(h);}
 }
 static void SelfTest(string folder){Directory.CreateDirectory(folder);foreach(long image in new long[]{ImageBase,0x180000000,0x7ff600000000})foreach(long offset in new long[]{0x20000000,0x20010000,0x60000000}){long cave=image+offset;byte[] b=BuildCave(image,cave),c=Config(image);if(c.Length!=288||b.Length>=0x8000)throw new Exception("Aumaan payload bounds");File.WriteAllBytes(Path.Combine(folder,"aumaan-"+image.ToString("x")+"-"+offset.ToString("x")+".bin"),b);File.WriteAllBytes(Path.Combine(folder,"config-"+image.ToString("x")+".bin"),c);}Console.WriteLine("Aumaan payload fixtures at three bases and three cave offsets; no game opened.");}
 public static int Main(string[] args){try{if(args.Length==2&&args[0]=="--self-test"){SelfTest(args[1]);return 0;}if(args.Length==2&&args[0]=="--attach-menu"){Attach(Int32.Parse(args[1]));return 0;}if(args.Length==3&&args[0]=="--capture-status"){Capture(Int32.Parse(args[1]),args[2]);return 0;}Console.WriteLine("--self-test folder; --attach-menu PID; --capture-status PID output.json");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}
